package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextProductionNativeBinding.Entry;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextWitnessResultTransport.Cut;
import org.kanger.ContextSignedUnaryModel.*;

/** Direct original-formula/whole-topology audit; never runs model builder/search/inference. */
final class ContextSignedUnaryModelAudit {
 static final class Receipt {final Ledger ledger;private Receipt(Ledger ledger){this.ledger=ledger;}}
 private static void require(boolean b,String why){if(!b)throw new IllegalStateException(why);}
 private static int fixed(Interpretation m,SemanticTermSnapshot value,Runnable work){require(value!=null,"Actual ordinary constant required");for(int n=0;n<m.points.size();n++){work.run();if(m.points.get(n).semanticallyEquals(value))return n;}throw new IllegalStateException("Original constant absent from model named basis");}
 private static void atom(String predicate,int arity,Set<String> vocabulary,Policy p,Runnable work){work.run();require(predicate!=null&&!predicate.isEmpty()&&predicate.length()<=256&&arity==1,"Uninterpreted unary native atom required");vocabulary.add(predicate);require(vocabulary.size()<=p.predicates,"Model vocabulary bound");}
 private static void shape(Entry e,Interpretation m,Set<String> vocabulary,Set<Source> witnesses,Policy p,Runnable work){
  work.run();if(e.bundle!=null){ContextWitnessBundle.Bundle b=e.bundle;require(e.kind==org.kanger.ContextProductionNativeBinding.Kind.WITNESS_BUNDLE&&e.clauses.isEmpty()&&b.source.equals(e.source)&&b.witnesses==1&&!b.atoms.isEmpty()&&b.atoms.size()<=8&&witnesses.add(e.source),"Whole one-binder signed bundle required");Integer assigned=m.witnesses.get(e.source);require(assigned!=null&&assigned>=0&&assigned<m.points.size(),"One concrete value per original bundle Source required");boolean used=false;for(ContextWitnessBundle.Atom a:b.atoms){atom(a.predicate,a.arguments.size(),vocabulary,p,work);ContextWitnessBundle.Slot t=a.arguments.get(0);require(t.witness>=-1&&t.witness<=0,"Unsupported existential binder");if(t.witness>=0){require(t.value==null,"Origin cannot masquerade as ordinary constant");used=true;}else fixed(m,t.value,work);}require(used,"Original witness binder must occur");
  }else{require(e.kind==org.kanger.ContextProductionNativeBinding.Kind.CLAUSES&&!e.clauses.isEmpty()&&e.clauses.size()<=8,"Whole ordinary/universal row required");for(Clause c:e.clauses){work.run();require(!c.literals.isEmpty()&&c.literals.size()<=8&&c.variables.size()<=1,"Bounded single-variable unary clause required");Set<Integer> actual=new LinkedHashSet<>();for(Atom a:c.literals){atom(a.predicate,a.arguments.size(),vocabulary,p,work);Slot t=a.arguments.get(0);require(t.variable>=-1,"Invalid original universal slot");if(t.variable>=0){require(t.value==null,"Variable cannot be replaced by an ordinary value");actual.add(t.variable);}else fixed(m,t.value,work);}require(actual.equals(c.variables),"Different complete original universal-variable inventory");}}
 }
 private static boolean literal(Interpretation m,String predicate,boolean positive,int value,Runnable work){work.run();return m.truth.get(predicate).get(value)==positive;}
 private static void truth(Entry e,Interpretation m,Runnable work){
  work.run();if(e.bundle!=null){int assigned=m.witnesses.get(e.source);for(ContextWitnessBundle.Atom a:e.bundle.atoms){ContextWitnessBundle.Slot t=a.arguments.get(0);require(literal(m,a.predicate,a.positive,t.witness>=0?assigned:fixed(m,t.value,work),work),"Original correlated bundle false in proposed interpretation");}}
  else for(Clause c:e.clauses){int count=c.variables.isEmpty()?1:m.points.size()+1;for(int value=0;value<count;value++){work.run();boolean yes=false;for(Atom a:c.literals){Slot t=a.arguments.get(0);yes|=literal(m,a.predicate,a.positive,t.variable>=0?value:fixed(m,t.value,work),work);}require(yes,"Original clause false in named/outside interpretation; not a no-model proof");}}
 }
 static Receipt inspect(Ledger l,Snapshot x,List<Snapshot> foreign,Map<Cut,Interpretation> models,Policy p,int maximumWork){
  require(l!=null&&x!=null&&foreign!=null&&foreign.size()<=15&&models!=null&&p!=null&&maximumWork>0&&l.x==x&&l.foreign.equals(foreign)&&l.models.equals(models)&&l.policy==p,"Exact original model ledger/request required");new Policy(p.rows,p.points,p.predicates,p.work);Runnable work=ContextGroundProductionRounds.budget(maximumWork);List<Snapshot> cuts=new ArrayList<>();cuts.add(x);cuts.addAll(foreign);Set<UUID> physical=new HashSet<>();Set<Source> sources=new HashSet<>();Set<Cut> expected=new LinkedHashSet<>();int index=0;
  for(int i=0;i<cuts.size();i++){work.run();Snapshot cut=cuts.get(i);require(cut!=null,"Actual logical cut required");ContextProductionFamilyAssembly.identity(cut,i==0,work);ContextProductionFamilyAssembly.claimContexts(cut,physical,work);require(expected.add(Cut.of(cut)),"Duplicate logical model cut");for(Snapshot member:cut.physicalMembers())for(Entry e:member.primary){work.run();require(index<p.rows&&index<l.rows.size()&&sources.add(e.source),"Complete unique original-row model manifest required");Row row=l.rows.get(index++);require(row!=null&&row.cut==cut&&row.member==member&&row.entry==e,"Different original physical row/cut/bundle binding");}}require(index==l.rows.size()&&l.models.keySet().equals(expected),"Missing/extra original row or logical model cut");
  // Preflight ALL cuts/rows/interpretations before any truth verification or receipt exposure.
  Map<Cut,List<Entry>> originals=new LinkedHashMap<>();for(Snapshot cut:cuts){work.run();Cut key=Cut.of(cut);Interpretation m=l.models.get(key);require(m!=null&&!m.points.isEmpty()&&m.points.size()<=p.points&&m.truth.size()<=p.predicates,"Actual bounded interpretation for every cut required");for(int n=0;n<m.points.size();n++){work.run();require(m.points.get(n)!=null,"Ordinary named basis value required");for(int j=0;j<n;j++){work.run();require(!m.points.get(n).semanticallyEquals(m.points.get(j)),"Semantically distinct named values required, not Origin disequality");}}
   List<Entry> entries=new ArrayList<>(x.primary);if(cut!=x)entries.addAll(cut.primary);Set<String> vocabulary=new LinkedHashSet<>();Set<Source> witnesses=new LinkedHashSet<>();for(Entry e:entries)shape(e,m,vocabulary,witnesses,p,work);require(m.truth.keySet().equals(vocabulary)&&m.witnesses.keySet().equals(witnesses),"Exact original predicate and Source-owned witness coverage required");for(Map.Entry<String,List<Boolean>> e:m.truth.entrySet()){work.run();require(e.getValue()!=null&&e.getValue().size()==m.points.size()+1,"Named truth plus ALL-other-admissible default required");for(Boolean b:e.getValue()){work.run();require(b!=null,"Every truth position required");}}originals.put(key,entries);
  }
  for(Map.Entry<Cut,List<Entry>> e:originals.entrySet())for(Entry row:e.getValue())truth(row,l.models.get(e.getKey()),work);return new Receipt(l);
 }
 static void check(Receipt r,Snapshot x,List<Snapshot> foreign,Map<Cut,Interpretation> models,Policy p,int work){require(r!=null,"Actual original unary model receipt required");inspect(r.ledger,x,foreign,models,p,work);}
}
